def _as_q_pochhammer_sum(term, k):
    r"""Try to write ``term`` as ``c + d*q**k``.

    Returns ``(c, d, q)`` when ``term`` is an ``Add`` of a part that is free
    of ``k`` and a part of the form ``d*q**k`` where ``d`` and ``q`` are also
    free of ``k``.  Returns ``None`` otherwise.
